func expectedParams(tmpl, path string) Params {
	// both start with '/'
	tparts := strings.Split(tmpl, "/")
	pparts := strings.Split(path, "/")
	var ps Params
	for i := 0; i < len(tparts); i++ {
		seg := tparts[i]
		if strings.HasPrefix(seg, ":") {
			ps = append(ps, Param{seg[1:], pparts[i]})
		} else if strings.HasPrefix(seg, "*") {
			ps = append(ps, Param{seg[1:], "/" + strings.Join(pparts[i:], "/")})
		}
	}
	return ps
}
```

