package gin

import (
	"strings"
	"testing"
)

func zzSubstitute(fullPath string, ps Params) (string, bool) {
	var sb strings.Builder
	pi := 0
	i := 0
	for i < len(fullPath) {
		c := fullPath[i]
		if c == ':' || c == '*' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			if pi >= len(ps) {
				return "", false
			}
			if c == '*' {
				s := sb.String()
				if strings.HasSuffix(s, "/") {
					sb.Reset()
					sb.WriteString(s[:len(s)-1])
				}
			}
			sb.WriteString(ps[pi].Value)
			pi++
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), pi == len(ps)
}

func zzWildcards(p string) int {
	n := 0
	for i := 0; i < len(p); i++ {
		if p[i] == ':' || p[i] == '*' {
			n++
		}
	}
	return n
}

func zzPerms(a []string) [][]string {
	if len(a) <= 1 {
		return [][]string{append([]string{}, a...)}
	}
	var out [][]string
	for i := range a {
		rest := append(append([]string{}, a[:i]...), a[i+1:]...)
		for _, p := range zzPerms(rest) {
			out = append(out, append([]string{a[i]}, p...))
		}
	}
	return out
}

func TestZZOrder(t *testing.T) {
	sets := [][]string{
		{"/repos/:owner/:repo/commits/:sha", "/repos/:owner/:repo/commits/:sha/comments"},
		{"/user/:name", "/user/:name/*action", "/user/groups"},
		{"/cmd/:tool/", "/cmd/:tool/:sub", "/cmd/whoami", "/cmd/whoami/root"},
		{"/a/:b/c", "/a/:b/d", "/a/x/c", "/a/x/d"},
		{"/:a/:b/:c", "/:a/:b/x", "/:a/y/:c", "/:a/y/x", "/z/:b/:c", "/z/y/x"},
		{"/x/:y/z", "/x/:y", "/x/w", "/x/w/z"},
		{"/v/:a/*b", "/v/:a/c", "/v/w/d"},
		{"/p/:q", "/p/:q/r", "/p/s", "/p/s/r", "/p/s/t"},
	}
	vals := []string{"a", "b", "ab", "abc", "x", "y", "z", "gin-gonic", "123", "whoami", "test", "s", "w", "v", "p"}
	for si, routes := range sets {
		for _, perm := range zzPerms(routes) {
			tree := &node{}
			bad := false
			for _, r := range perm {
				func() {
					defer func() {
						if rec := recover(); rec != nil {
							bad = true
						}
					}()
					tree.addRoute(r, fakeHandler(r))
				}()
				if bad {
					break
				}
			}
			if bad {
				continue
			}
			// requests: substitute each value in each route
			var reqs []string
			for _, r := range routes {
				for _, v1 := range vals {
					for _, v2 := range vals {
						var sb strings.Builder
						i := 0
						vi := 0
						for i < len(r) {
							c := r[i]
							if c == ':' || c == '*' {
								j := i + 1
								for j < len(r) && r[j] != '/' {
									j++
								}
								v := v1
								if vi == 1 {
									v = v2
								}
								if c == '*' {
									sb.WriteString("/" + v)
								} else {
									sb.WriteString(v)
								}
								vi++
								i = j
								continue
							}
							sb.WriteByte(c)
							i++
						}
						reqs = append(reqs, sb.String())
					}
				}
				reqs = append(reqs, r)
			}
			for _, req := range reqs {
				value := tree.getValue(req, getParams(), getSkippedNodes(), false)
				if value.handlers == nil {
					continue
				}
				var ps Params
				if value.params != nil {
					ps = *value.params
				}
				got, ok := zzSubstitute(value.fullPath, ps)
				if !ok || got != req {
					t.Errorf("set %d perm %v: req %q matched %q params %v (reconstructed %q ok=%v)", si, perm, req, value.fullPath, ps, got, ok)
