package gin

import (
	"math/rand"
	"strings"
	"testing"
)

func zzSubstitute(fullPath string, ps Params) (string, bool) {
	var sb strings.Builder
	pi := 0
	i := 0
	for i < len(fullPath) {
		c := fullPath[i]
		if c == ':' || c == '*' {
			j := i + 1
			for j < len(fullPath) && fullPath[j] != '/' {
				j++
			}
			if pi >= len(ps) {
				return "", false
			}
			if c == '*' {
				s := sb.String()
				if strings.HasSuffix(s, "/") {
					sb.Reset()
					sb.WriteString(s[:len(s)-1])
				}
			}
			sb.WriteString(ps[pi].Value)
			pi++
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), pi == len(ps)
}

func zzWildcards(p string) int {
	n := 0
	for i := 0; i < len(p); i++ {
		if p[i] == ':' || p[i] == '*' {
			n++
		}
	}
	return n
}

func zzGenRoute(rnd *rand.Rand, i int) string {
	lits := []string{"a", "b", "c", "ab", "abc", "x", "y", "z", "aa", "bc"}
	n := 1 + rnd.Intn(4)
	var sb strings.Builder
	for s := 0; s < n; s++ {
		sb.WriteByte('/')
		switch k := rnd.Intn(4); k {
		case 0:
			sb.WriteString(":" + string(rune('p'+rnd.Intn(3))))
		case 1:
			if s == n-1 {
				sb.WriteString("*" + string(rune('c'+rnd.Intn(2))))
			} else {
				sb.WriteString(lits[rnd.Intn(len(lits))])
			}
		default:
			sb.WriteString(lits[rnd.Intn(len(lits))])
		}
	}
	if rnd.Intn(4) == 0 {
		sb.WriteByte('/')
	}
	return sb.String()
}

func zzReqFromRoute(rnd *rand.Rand, r string) string {
	vals := []string{"a", "b", "c", "ab", "abc", "x", "y", "z", "aa", "bc", "abcabc", "1"}
	var sb strings.Builder
	i := 0
	for i < len(r) {
		c := r[i]
		if c == ':' || c == '*' {
			j := i + 1
			for j < len(r) && r[j] != '/' {
				j++
			}
			if c == '*' {
				sb.WriteString("/" + vals[rnd.Intn(len(vals))])
				if rnd.Intn(2) == 0 {
					sb.WriteString("/" + vals[rnd.Intn(len(vals))])
				}
			} else {
				sb.WriteString(vals[rnd.Intn(len(vals))])
			}
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

func TestZZRandom(t *testing.T) {
	bad := 0
	for seed := int64(0); seed < 400 && bad < 10; seed++ {
		rnd := rand.New(rand.NewSource(seed))
		nr := 3 + rnd.Intn(4)
		routes := make([]string, 0, nr)
		for i := 0; i < nr; i++ {
			routes = append(routes, zzGenRoute(rnd, i))
		}
		tree := &node{}
		ok := true
		for _, r := range routes {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						ok = false
					}
				}()
				tree.addRoute(r, fakeHandler(r))
			}()
			if !ok {
				break
			}
		}
		if !ok {
			continue
		}
		var reqs []string
		for _, r := range routes {
			for k := 0; k < 8; k++ {
				reqs = append(reqs, zzReqFromRoute(rnd, r))
			}
			reqs = append(reqs, r, r+"/")
		}
		for _, req := range reqs {
			value := tree.getValue(req, getParams(), getSkippedNodes(), false)
			if value.handlers == nil {
				continue
			}
			var ps Params
			if value.params != nil {
				ps = *value.params
			}
			got, ok2 := zzSubstitute(value.fullPath, ps)
			if !ok2 || got != req {
				t.Errorf("seed %d routes %v: req %q matched %q params %v (reconstructed %q ok=%v)", seed, routes, req, value.fullPath, ps, got, ok2)
				bad++
				break
			}
			if len(ps) != zzWildcards(value.fullPath) {
				t.Errorf("seed %d routes %v: req %q matched %q: %d params want %d (%v)", seed, routes, req, value.fullPath, len(ps), zzWildcards(value.fullPath), ps)
				bad++
				break
			}
		}
	}
}
